import React, { useState } from "react";
import { Link } from "react-router-dom";
import "bootstrap-icons/font/bootstrap-icons.css";
import "./AdminS.css";

export default function SuperAdminPage({ onLogout, onChangeUser }) {
  const [menuOpen, setMenuOpen] = useState(false);

  const toggleMenu = () => {
    setMenuOpen(!menuOpen);
  };

  const handleLogout = () => {
    setMenuOpen(false);
    onLogout();
  };

  const handleChangeUser = () => {
    setMenuOpen(false);
    onChangeUser();
  };

  return (
    <div className="superAdmin-container">
      <header className="superAdmin-header">
        <div className="superAdmin-header-content">
          <h1 className="superAdmin-header-title">TalkinPon - Super Administrador</h1>

          {/* Icono de usuario */}
          <div className="superAdmin-user-menu">
            <i
              className="bi bi-person-circle superAdmin-user-icon-link"
              onClick={toggleMenu}
            ></i>

            {menuOpen && (
              <div className="superAdmin-dropdown">
                <button onClick={handleLogout}>Cerrar sesión</button>
                <button onClick={handleChangeUser}>Cambiar usuario</button>
              </div>
            )}
          </div>
        </div>
      </header>

      <main className="superAdmin-main">
        <div className="superAdmin-card">
          <h2 className="superAdmin-welcome">Bienvenido Super Administrador</h2>
          <p className="superAdmin-description">
            Desde aquí puedes gestionar todos los módulos del sistema.
          </p>

          {/* Opciones del dashboard */}
          <div className="superAdmin-options">
            <div className="superAdmin-option">
              <h3>Procesos Administrativos</h3>
              <p>Gestionar kardex, constancias, titulación, créditos y otros procesos</p>
            </div>
            <div className="superAdmin-option">
              <h3>Ubicaciones</h3>
              <p>Administrar edificios, salones, mapas y ubicaciones del campus</p>
            </div>
            <div className="superAdmin-option">
              <h3>Usuarios</h3>
              <p>Gestionar usuarios, permisos y roles del sistema</p>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}
